  sflbPlaceBubbles(capped);
  capped.forEach((b) => {
    const el = sflbCreateBubbleEl(b);
    b.el = el;
    stageEl.appendChild(el);
    sflbWireBubbleDrag(b);
    el.style.transform = "translate3d(" + (b.x - b.r).toFixed(1) + "px," + (b.y - b.r).toFixed(1) + "px,0)";
  });
