var QTY_FORMAT = new Intl.NumberFormat("en-US", {
  minimumFractionDigits: 2,
  maximumFractionDigits: 2
});
var FISH_TIERS = ["Basic", "Advanced", "Expert"];
var FISH_TIER_ICONS = {
  Basic: "Anchovy",
  Advanced: "Red Snapper",
  Expert: "Tuna"
};
var FISH_TIER_LABELS = {
  Basic: "Basic Fish",
  Advanced: "Advance Fish",
  Expert: "Expert Fish"
};
var COMPOSTER_ORDER = ["Compost Bin", "Turbo Composter", "Premium Composter"];
var PROCESSING_ORDER = ["Fish Flake", "Fish Stick", "Fish Oil", "Crab Stick"];
function iconHtml(name) {
  return `<span class="ss-icon">${getIcon(name)}</span>`;
}
function lineHtml(name, qty) {
  const amount = qty === void 0 ? "" : ` <span class="ss-line-qty">\xD7${QTY_FORMAT.format(qty)}</span>`;
  return `<div class="ss-line">${iconHtml(name)}<span class="ss-line-name">${escapeHtml(name)}${amount}</span></div>`;
}
function subHtml(name) {
  return `<div class="ss-sub ss-sub-tier">${iconHtml(FISH_TIER_ICONS[name] || name)}<span>${escapeHtml(FISH_TIER_LABELS[name] || name)}</span></div>`;
}
function cardHtml(season, suffix, body) {
  return `<div class="cb-item ss-card">
    <div class="ss-card-head">${SEASON_EMOJI[season]}<span>${season} ${suffix}</span></div>
    ${body}
  </div>`;
}
function productCardHtml(name, body) {
  return `<div class="cb-item ss-card">
    <div class="ss-card-head">${iconHtml(name)}<span>${escapeHtml(name)}</span></div>
    ${body}
  </div>`;
}
function seasonSubHtml(season) {
  return `<div class="ss-sub">${SEASON_EMOJI[season]}<span>${season}</span></div>`;
}
function containerHtml(iconName, label, cards, cols) {
  return `<div class="cb-column ss-container">
    <div class="cb-column-label ss-label">${iconHtml(iconName)}<span>${escapeHtml(label)}</span></div>
    <div class="ss-grid${cols ? " ss-cols-" + cols : ""}">${cards}</div>
  </div>`;
}
function namesBody(names) {
  return names.map((n) => lineHtml(n)).join("");
}
function recipeBody(inv) {
  return Object.keys(inv).map((n) => lineHtml(n, inv[n])).join("");
}
function lavaPitHtml() {
  const cards = SEASON_ORDER.map((season) => {
    const mats = LAVA_PIT_RECIPES[season].materials;
    return cardHtml(season, "Recipes", mats.map((m) => lineHtml(m.name, m.qty)).join(""));
  }).join("");
  return containerHtml("Lava Pit", "Lava Pit Recipe", cards);
}
function listContainerHtml(iconName, label, suffix, bySeason) {
  const cards = SEASON_ORDER.map((season) => cardHtml(season, suffix, namesBody(bySeason[season]))).join("");
  return containerHtml(iconName, label, cards);
}
function fishingHtml() {
  const cards = SEASON_ORDER.map((season) => {
    const body = FISH_TIERS.map((tier) => {
      const list = SEASONS_DATA.fish[season][tier];
      return list.length ? subHtml(tier) + namesBody(list) : "";
    }).join("");
    return cardHtml(season, "Fish", body);
  }).join("");
  return containerHtml("Rod", "Fishing", cards);
}
function processingHtml() {
  const cards = PROCESSING_ORDER.map((product) => {
    const body = SEASON_ORDER.map((season) => seasonSubHtml(season) + recipeBody(SEASONS_DATA.processing[product][season])).join("");
    return productCardHtml(product, body);
  }).join("");
  return containerHtml("Fish Flake", "Fish Processing", cards, 4);
}
function composterHtml() {
  const cards = COMPOSTER_ORDER.map((name) => {
    const body = SEASON_ORDER.map((season) => seasonSubHtml(season) + recipeBody(SEASONS_DATA.composters[name][season])).join("");
    return productCardHtml(name, body);
  }).join("");
  return containerHtml("Compost Bin", "Composter", cards, 3);
}
function renderSeasonsPanel() {
  const body = document.getElementById("seasonsBody");
  if (!body) return;
  body.innerHTML = `<div class="ss-stack">
    ${lavaPitHtml()}
    ${listContainerHtml("Sunflower", "Crops", "Crops", SEASONS_DATA.crops)}
    ${listContainerHtml("Apple", "Fruits", "Fruits", SEASONS_DATA.fruits)}
    ${listContainerHtml("Red Pansy", "Flowers", "Flowers", SEASONS_DATA.flowers)}
    ${fishingHtml()}
    ${processingHtml()}
    ${composterHtml()}
  </div>`;
}

// src/leaderboard.js
function lbApiUrl() {
  return SFL_COMMUNITY_PROXY_BASE + "community/data?type=statsLeaderboard";
}
var LB_BOARDS = [
  { name: "coins", tab: "Coins", icon: () => COIN_ICON },
  { name: "experience", tab: "XP", icon: () => getIcon("Experience") },
  { name: "newPlayerExperience", tab: "New Players", icon: () => getIcon("Experience") },
  { name: "sunflowers", tab: "Sunflowers", icon: () => getIcon("Sunflower") },
  { name: "kale", tab: "Kale", icon: () => getIcon("Kale") },
  { name: "chores", tab: "Chores", icon: () => "" },
  { name: "deliveries", tab: "Deliveries", icon: () => "" },
  { name: "dailyLoginStreak", tab: "Login Streak", icon: () => "" },
  { name: "diggingStreak", tab: "Digging Streak", icon: () => getIcon("Sand Shovel") }
];
var lbData = null;
var lbLoading = false;
var lbError = null;
var lbLog = [];
var lbFromCache = false;
var LB_CACHE_KEY = "gc_leaderboard_cache";
function lbSaveCache(data) {
  try {
    const boards = {};
    Object.keys(data.boards || {}).forEach((k) => {
      const b = data.boards[k];
      boards[k] = {
        name: b.name,
        title: b.title,
        description: b.description,
        players: (b.players || []).map((p) => ({ rank: p.rank, farmId: p.farmId, username: p.username, level: p.level, ascension: p.ascension, count: p.count }))
      };
    });
    localStorage.setItem(LB_CACHE_KEY, JSON.stringify({ reportDate: data.reportDate, lastUpdated: data.lastUpdated, activeSince: data.activeSince, scanned: data.scanned, boards }));
  } catch (e) {
  }
}
function lbLoadCache() {
  try {
    const raw = localStorage.getItem(LB_CACHE_KEY);
    const parsed = raw ? JSON.parse(raw) : null;
    return parsed && parsed.boards ? parsed : null;
  } catch (e) {
    return null;
  }
}
var lbActiveBoard = LB_BOARDS[0].name;
function lbFormatDate(ms) {
  if (!ms) return "";
  try {
    return new Date(ms).toISOString().replace("T", " ").slice(0, 16) + " UTC";
  } catch (e) {
    return "";
  }
}
function lbInfoHtml() {
  if (lbLoading && !lbData) {
    return `<div class="cb-note">Loading the daily top 100 stat boards from the Sunflower Land community API\u2026</div>`;
  }
  if (lbError) {
    return `<div class="cb-note">${escapeHtml(lbError)}</div>`;
  }
  if (!lbData) {
    return `<div class="cb-note">No boards found. API answers: ${escapeHtml(lbLog.join(" | ") || "none")}</div>`;
  }
  const scanned = lbData.scanned != null ? fmtInt(lbData.scanned) : "?";
  const updated = lbFormatDate(lbData.lastUpdated);
  const since = lbFormatDate(lbData.activeSince);
  return `<div class="cb-note">Top 100 farms for each of the ${LB_BOARDS.length} daily stat boards (coins, XP, new player XP, sunflowers, kale, chores, deliveries, daily login streak and digging streak), ranked over ${escapeHtml(scanned)} farms that played in the last 30 days${since ? " (since " + escapeHtml(since.slice(0, 10)) + ")" : ""}. Report day: ${escapeHtml(String(lbData.reportDate || "?"))} (UTC)${updated ? ", last updated " + escapeHtml(updated) : ""}. Boards are built once a day and show the latest complete day.${lbFromCache ? " The API has no published boards right now, so this is the last copy saved on this device." : ""} Coins, XP, sunflowers and kale are current holdings, chores and deliveries are all-time totals, and the streaks are consecutive days.</div>`;
}
function lbRowHtml(player) {
  const asc = player.ascension > 0 ? ` \xB7 A${escapeHtml(String(player.ascension))}` : "";
  return `<div class="cb-item lb-row" title="Farm #${escapeHtml(String(player.farmId))}">
    <span class="lb-rank">${escapeHtml(String(player.rank))}</span>
    <span class="lb-name cb-item-name">${escapeHtml(String(player.username))}</span>
    <span class="lb-lvl">Lvl ${escapeHtml(String(player.level))}${asc}</span>
    <span class="lb-count cb-item-cost">${fmtInt(player.count)}</span>
  </div>`;
}
function lbBoardHtml(def) {
  const board = lbData && lbData.boards ? lbData.boards[def.name] : null;
  const title = board && board.title ? board.title : def.tab;
  const desc = board && board.description ? board.description : "";
  const players = board && Array.isArray(board.players) ? board.players : [];
  const rows = players.length ? players.map(lbRowHtml).join("") : `<div class="lb-empty">No players on this board</div>`;
  const icon = def.icon();
  return `<div class="cb-column lb-board${def.name === lbActiveBoard ? " lb-active" : ""}" data-lb-board="${def.name}">
    <div class="cb-column-label">${icon ? icon + " " : ""}${escapeHtml(title)}</div>
    ${desc ? `<div class="lb-desc">${escapeHtml(desc)}</div>` : ""}
    <div class="lb-list">${rows}</div>
  </div>`;
}
function lbTabsHtml() {
  const tabs = LB_BOARDS.map((def) => `<button type="button" class="market-tab-btn${def.name === lbActiveBoard ? " active" : ""}" data-lb-tab="${def.name}">${escapeHtml(def.tab)}</button>`).join("");
  return `<div class="market-tabs lb-tabs" id="lbTabs">${tabs}</div>`;
}
function lbDateOffset(days) {
  return new Date(Date.now() - days * 864e5).toISOString().slice(0, 10);
}
async function lbFetchDay(dateStr) {
  const url = lbApiUrl() + (dateStr ? "&date=" + dateStr : "");
  const res = await fetch(url);
  if (res.status === 429) throw new Error("Too many requests, try again in a few seconds");
  let json = null;
  try {
    json = await res.json();
  } catch (e) {
  }
  const payload = json && json.boards ? json : json && json.data && json.data.boards ? json.data : null;
  lbLog.push((dateStr || "default") + ": " + res.status + (payload ? " ok" : json && json.error ? " " + json.error : " no boards"));
  return { status: res.status, data: payload };
}
async function lbFetch() {
  if (lbLoading || lbData) return;
  lbLoading = true;
  lbError = null;
  lbLog = [];
  lbRender();
  try {
    let found = null;
    for (let i = 0; i <= 6 && !found; i++) {
      const r = await lbFetchDay(i === 0 ? "" : lbDateOffset(i));
      if (r.data) found = r.data;
    }
    if (found) {
      lbData = found;
      lbFromCache = false;
      lbSaveCache(found);
    } else {
      const cached = lbLoadCache();
      if (cached) {
        lbData = cached;
        lbFromCache = true;
      }
    }
  } catch (e) {
    lbError = "Couldn't load the leader boards" + (e && e.message ? " \u2014 " + e.message : "") + ".";
  } finally {
    lbLoading = false;
    lbRender();
  }
}
function lbRender() {
  const body = $("leaderboardBody");
  if (!body) return;
  const scrollTops = {};
  body.querySelectorAll(".lb-board").forEach((el) => {
    const list = el.querySelector(".lb-list");
    if (list) scrollTops[el.getAttribute("data-lb-board")] = list.scrollTop;
  });
  const showBoards = !!lbData;
  body.innerHTML = `
    <div class="cb-title">Leader Board</div>
    ${lbInfoHtml()}
    ${showBoards ? lbTabsHtml() : ""}
    ${showBoards ? `<div class="lb-columns">${LB_BOARDS.map(lbBoardHtml).join("")}</div>` : ""}
  `;
  body.querySelectorAll(".lb-board").forEach((el) => {
    const list = el.querySelector(".lb-list");
    const top = scrollTops[el.getAttribute("data-lb-board")];
    if (list && top) list.scrollTop = top;
  });
}
function renderLeaderboardPanel() {
  lbRender();
  lbFetch();
}
document.addEventListener("click", (e) => {
  const tab = e.target.closest("[data-lb-tab]");
  if (!tab) return;
  lbActiveBoard = tab.getAttribute("data-lb-tab");
  document.querySelectorAll("#leaderboardBody [data-lb-tab]").forEach((btn) => {
    btn.classList.toggle("active", btn.getAttribute("data-lb-tab") === lbActiveBoard);
  });
  document.querySelectorAll("#leaderboardBody .lb-board").forEach((el) => {
    el.classList.toggle("lb-active", el.getAttribute("data-lb-board") === lbActiveBoard);
  });
});

// src/map.js
var MAP_CELL = 38;
var mapPicks = [];
var mapPicksState = null;
var MAP_AXIS = 24;
function mapFmtYield(v) {
  return typeof v === "number" && isFinite(v) ? v.toFixed(2) : "";
}
function mapFmtWait(sec) {
  if (!(sec > 0)) return "Ready";
  const d = Math.floor(sec / 86400);
  const h = Math.floor(sec % 86400 / 3600);
  const m = Math.floor(sec % 3600 / 60);
  const parts = [];
  if (d) parts.push(d + "d");
  if (h) parts.push(h + "h");
  if (!d) parts.push(m + "m");
  return "Ready in " + parts.join(" ");
}
var MAP_PROC_CODES = {
  "Native": "N",
  "Tough Tree": "T",
  "Rock Golem": "G",
  "Tree Turnaround": "R",
  "Pickaxe Shark": "P",
  "Crimstone Clam": "C"
};
function mapProcChipsHtml(procs) {
  if (!procs || !procs.length) return "";
  const chips = procs.map((p) => {
    const base = p.replace(/ x\d+$/, "");
    const count = (p.match(/ x(\d+)$/) || [])[1];
    return `<span class="map-node-proc proc-${(MAP_PROC_CODES[base] || "?").toLowerCase()}">${MAP_PROC_CODES[base] || "?"}${count || ""}</span>`;
  }).join("");
  return `<span class="map-node-procs">${chips}</span>`;
}
function mapNodeHtml(n, minX, maxY) {
  const left = MAP_AXIS + (n.x - minX) * MAP_CELL;
  const top = MAP_AXIS + (maxY - n.y) * MAP_CELL;
  const tip = `${n.name} (${n.x}, ${n.y})${n.w > 1 || n.h > 1 ? ` ${n.w}x${n.h}` : ""}${n.ready === false || n.remainingSec > 0 ? " - " + mapFmtWait(n.remainingSec) : n.ready === true ? " - Ready" : ""}${n.procs && n.procs.length ? " - Procs: " + n.procs.join(", ") : ""}`;
  const pickable = !!n.mapKey && n.ready === true;
  return `<div class="map-node${pickable ? " map-node-pickable" : ""}${n.pickNo ? " map-node-picked" : ""}"${pickable ? ` data-map-key="${escapeHtml(n.mapKey)}"` : ""} title="${escapeHtml(tip)}" style="left:${left}px;top:${top}px;width:${n.w * MAP_CELL}px;height:${n.h * MAP_CELL}px;">
    <span class="map-node-badge${n.badge ? " has-badge" : ""}">${n.badge ? escapeHtml(n.badge) : "&nbsp;"}</span>
    <span class="map-node-icon">${getIcon(n.name)}</span>
    <span class="map-node-yield${n.procs && n.procs.length ? " has-proc" : ""}">${mapFmtYield(n.yieldVal)}</span>
    ${mapProcChipsHtml(n.procs)}
    ${n.pickNo || n.autoNo ? `<span class="map-node-pick${n.pickNo ? "" : " map-node-auto"}">#${n.pickNo || n.autoNo}</span>` : ""}
  </div>`;
}
function mapGridHtml(nodes) {
  let minX = Infinity;
  let maxX = -Infinity;
  let minY = Infinity;
  let maxY = -Infinity;
  nodes.forEach((n) => {
    minX = Math.min(minX, n.x);
    maxX = Math.max(maxX, n.x + n.w - 1);
    maxY = Math.max(maxY, n.y);
    minY = Math.min(minY, n.y - n.h + 1);
  });
  const cols = maxX - minX + 1;
  const rows = maxY - minY + 1;
  const width = MAP_AXIS + cols * MAP_CELL;
  const height = MAP_AXIS + rows * MAP_CELL;
  let axes = "";
  for (let i = 0; i < cols; i++) {
    axes += `<span class="map-axis-x" style="left:${MAP_AXIS + i * MAP_CELL}px;width:${MAP_CELL}px;">${minX + i}</span>`;
  }
  for (let j = 0; j < rows; j++) {
    axes += `<span class="map-axis-y" style="top:${MAP_AXIS + j * MAP_CELL}px;height:${MAP_CELL}px;width:${MAP_AXIS}px;">${maxY - j}</span>`;
  }
  return `<div class="map-scroll"><div class="map-grid" style="width:${width}px;height:${height}px;--map-cell:${MAP_CELL}px;--map-axis:${MAP_AXIS}px;">${axes}${nodes.map((n) => mapNodeHtml(n, minX, maxY)).join("")}</div></div>`;
}
var mapGuideOpen = false;
var MAP_GUIDE_LEGEND = [
  ["Native", "Native +1"],
  ["Tough Tree", "Tough Tree x3"],
  ["Rock Golem", "Rock Golem +2"],
  ["Tree Turnaround", "Tree Turnaround (extra instant chops are already added to the yield)"],
  ["Pickaxe Shark", "Pickaxe Shark"],
  ["Crimstone Clam", "Crimstone Clam"]
];
function mapGuideHtml() {
  const rows = MAP_GUIDE_LEGEND.map(([key, text]) => {
    const code = MAP_PROC_CODES[key];
    return `<div class="map-guide-item"><span class="map-node-proc proc-${code.toLowerCase()} map-guide-code">${code}</span><span class="map-guide-text">${escapeHtml(text)}</span></div>`;
  }).join("");
  return `<details class="map-guide cb-column"${mapGuideOpen ? " open" : ""}>
    <summary class="map-guide-summary">Guide</summary>
    <div class="map-guide-body">
      <p>Exact tile coordinates from your synced farm. The number above an icon is the streak (harvests or mines left, mines until the oil bonus, S for a swarm). The number below is the predicted yield.</p>
      <p>Every node on the map has a # tag. It is the order in which to collect that node type: #1 first, then #2, then #3. Crops, fruit, flower beds, trees, stone, iron, gold, crimstone, oil, lava pits, sunstone and beehives each count in their own list.</p>
      <p>You must collect in this order for the procs on the map to be accurate in the real game. The game does not store a proc on a node. It keeps one roll counter per node type that goes up by one every time you collect a node of that type, so the Nth collect is the one that procs. A green yield with letters is the node that gets the proc at its number. For example, if stone #4 shows +2, your 4th stone collect gives +2 only if you collected #1, #2 and #3 before it.</p>
      <p>Skipping a number, collecting a node of that type that is not in order, or collecting since your last sync shifts every roll after it. Sync again after you finish collecting. You can stop after the last proc you want. Tap a ready node to lock it to your own order, and tap it again to unlock. Nodes still recovering are numbered after the ready ones, in the order they become ready. Flower beds, oil and sunstone do not depend on the order, so their numbers only show a suggested order.</p>
      ${mapPicks.length ? `<button type="button" class="map-reset-order">Reset order</button>` : ""}
      <p>A green yield with letters on the corner marks a proc:</p>
      <div class="map-guide-legend">${rows}</div>
      <p>Honey shows what the hive gives if harvested now.</p>
    </div>
  </details>`;
}
function mapBindPicks(body) {
  const grid = body.querySelector(".map-grid");
  if (grid) {
    grid.addEventListener("click", (e) => {
      const el = e.target.closest(".map-node-pickable");
      if (!el) return;
      const key = el.getAttribute("data-map-key");
      const at = mapPicks.indexOf(key);
      if (at >= 0) mapPicks.splice(at, 1);
      else mapPicks.push(key);
      renderMapPanel();
    });
  }
  const reset = body.querySelector(".map-reset-order");
  if (reset) {
    reset.addEventListener("click", () => {
      mapPicks = [];
      renderMapPanel();
    });
  }
}
function mapBindGuide(body) {
  const guide = body.querySelector(".map-guide");
  if (!guide) return;
  guide.addEventListener("toggle", () => {
    mapGuideOpen = guide.open;
  });
}
function renderMapPanel() {
  const body = $("mapBody");
  if (!body) return;
  const prevScroll = body.querySelector(".map-scroll");
  const prevState = {
    bodyTop: body.scrollTop,
    mapTop: prevScroll ? prevScroll.scrollTop : 0,
    mapLeft: prevScroll ? prevScroll.scrollLeft : 0
  };
  let nodes = [];
  if (farmPanelGameState !== mapPicksState) {
    mapPicksState = farmPanelGameState;
    mapPicks = [];
  }
  if (farmPanelGameState) {
    try {
      nodes = farmPanelComputeMapNodes(farmPanelGameState, mapPicks);
    } catch (e) {
      nodes = [];
    }
  }
  if (!farmPanelGameState) {
    body.innerHTML = `
      <div class="cb-title">Map</div>
      <div class="cb-note">Sync your farm to see the map.</div>
    `;
    return;
  }
  if (!nodes.length) {
    body.innerHTML = `
      <div class="cb-title">Map</div>
      <div class="cb-note">No placed nodes were found in your synced farm.</div>
    `;
    return;
  }
  body.innerHTML = `
    <div class="cb-title">Map</div>
    ${mapGuideHtml()}
    <div class="cb-column">${mapGridHtml(nodes)}</div>
  `;
  mapBindGuide(body);
  mapBindPicks(body);
  const nextScroll = body.querySelector(".map-scroll");
  body.scrollTop = prevState.bodyTop;
  if (nextScroll) {
    nextScroll.scrollTop = prevState.mapTop;
    nextScroll.scrollLeft = prevState.mapLeft;
  }
}

