function renderCmModules() {
  const wrap = $("cmModulesRow");
  if (!wrap) return;
  const mods = [{
    key: "I",
    label: "Module I",
    crops: "Rhubarb, Zucchini"
  }, {
    key: "II",
    label: "Module II",
    crops: "Carrot, Cabbage"
  }, {
    key: "III",
    label: "Module III",
    crops: "Yam, Broccoli"
  }];
  wrap.innerHTML = mods.map((mo) => {
    const unlocked = isSkillActive(CM_MODULE_SKILL_IDS[mo.key]);
    return `<div class="cm-module-chip${unlocked ? " unlocked" : ""}" data-cm-module="${mo.key}" title="${escapeHtml(mo.crops)}">
      ${unlocked ? "\u2705" : "\u{1F512}"} ${mo.label}
    </div>`;
  }).join("");
  wrap.querySelectorAll("[data-cm-module]").forEach((el) => {
    el.onclick = () => {
      const key = el.dataset.cmModule;
      if (isSkillActive(CM_MODULE_SKILL_IDS[key])) return;
      toast(`\u{1F512} Select the "${CM_MODULE_SKILL_NAMES[key]}" skill in your Skill Tree to unlock this module`);
    };
  });
}
