    const b = computeCropMachineBatch(name, base.seedQty);
    const isProfit = b.profitFlower >= 0;
    return `<tr class="${locked ? "is-locked" : ""}">
      <td>${locked ? "\u{1F512}" : getIcon(name)} ${escapeHtml(name)}${cmModuleTagHtml(name)}</td>
      <td>${fmt(base.seedQty)}</td>
      <td>${formatDuration(b.timeSec)}</td>
      <td>${fmt(b.oilQty)}</td>
      <td>${fmt(b.yieldQty)}</td>
      <td>${fmt(b.costFlower)}</td>
      <td>${fmt(b.sellFlower)}</td>
      <td class="${isProfit ? "is-profit" : "is-loss"}">${isProfit ? "+" : ""}${fmt(b.profitFlower)}</td>
    </tr>`;
