document.addEventListener("click", (e) => {
  const target = e.target;
  if (!target || !target.closest) return;
  const logBtn = target.closest("[data-dh-log]");
  if (logBtn) {
    e.stopPropagation();
    e.preventDefault();
    document.dispatchEvent(new CustomEvent("dh-open-log", {
      detail: {
        farm: logBtn.getAttribute("data-dh-log") || ""
      }
    }));
    return;
  }
  if (target.closest("[data-dh-close]")) {
    e.stopPropagation();
    closeDailyPop();
    return;
  }
  const backdrop = target.closest(".dh-pop-back");
  if (backdrop && target === backdrop) {
    closeDailyPop();
    return;
  }
  const badge = target.closest(".daily-harvest-badge");
  if (!badge) return;
  e.stopPropagation();
  e.preventDefault();
  openDailyPop(badge);
}, true);
document.addEventListener("keydown", (e) => {
  if (e.key === "Escape") closeDailyPop();
  if ((e.key === "Enter" || e.key === " ") && e.target && e.target.classList && e.target.classList.contains("daily-harvest-badge")) {
    e.preventDefault();
    e.stopPropagation();
    openDailyPop(e.target);
  }
}, true);

// src/harvest_log.js
var HARVEST_LOG_BASE = "https://sfl-harvest-log.bossweki.workers.dev";
var SENT_KEY = "hl_hlog_sent_v1";
var SETTLE_MS = 1200;
var FALLBACK_MS = 6e3;
var REQUEST_TIMEOUT_MS = 8e3;
var NODE_ORDER = ["Wood", "Stone", "Iron", "Gold", "Crimstone", "Oil"];
