  if (!farmPanelIsWithinTurtleAOE(turtlePos, {
    x: node.x,
    y: node.y
  })) return false;
  const aoeState = farmPanelField(g, "aoe") || {};
  const dx = node.x - turtlePos.x;
  const dy = node.y - turtlePos.y;
