  const totalYieldPerCycle = getResourceTieredYieldTotal(name, boosted.yieldVal, boosted.perTierYield);
  return {
    costPerUnit,
    totalToolCost,
    yieldPer: boosted.yieldVal,
    timeSec: boosted.timeVal,
    tool: data.tool,
    breakdown,
    activeBoosts: boosted.activeBoosts,
    nodeCount,
    toolUsageTotal,
    totalYieldPerCycle,
    perTierYield: boosted.perTierYield
  };
