function computeBudFarmCropEffects(typeId, stemId, auraId) {
  const type = BUD_CROP_TYPES.find((t) => t.id === typeId) || BUD_CROP_TYPES[0];
  const stem = BUD_CROP_STEMS.find((s) => s.id === stemId) || BUD_CROP_STEMS[0];
  const aura = BUD_AURAS.find((a) => a.id === auraId) || BUD_AURAS[0];
  const result = {};
  function keyFor(eff) {
    if (eff.tier === "All") return {
      key: "global",
      scope: "global",
      target: null
    };
    if (eff.tier) return {
      key: "tier:" + eff.tier,
      scope: "tier",
      target: eff.tier
    };
    return {
      key: "crop:" + eff.crop,
      scope: "crop",
      target: eff.crop
    };
  }
  function addComponent(comp) {
    if (!comp || !comp.effects) return;
    comp.effects.forEach((eff) => {
      const k = keyFor(eff);
      if (!result[k.key]) result[k.key] = {
        scope: k.scope,
        target: k.target,
        yieldAdd: 0,
        timePct: 0
      };
      if (eff.yieldAdd) result[k.key].yieldAdd += eff.yieldAdd * aura.mult;
      if (eff.timePct) result[k.key].timePct += eff.timePct * aura.mult;
    });
  }
  addComponent(type);
  addComponent(stem);
  Object.values(result).forEach((r) => {
    if (r.timePct > 0.95) r.timePct = 0.95;
  });
  return result;
}
