async function performLiveSync() {
  if (liveSyncInFlight) return null;
  liveSyncInFlight = true;
  const btns = document.querySelectorAll(".js-sync-live-prices-btn");
  btns.forEach((btn) => {
    btn.classList.add("is-loading");
    btn.textContent = "\u{1F504} Syncing...";
  });
  try {
    const { p2p, nft, updatedAt } = await fetchLivePrices(true);
    setLivePrices(p2p, updatedAt, nft);
    const result = applyLivePricesToMarket(true);
    return {
      ok: true,
      result
    };
  } catch (e) {
    console.error("Live price sync failed:", e);
    return {
      ok: false,
      error: e
    };
  } finally {
    liveSyncInFlight = false;
    btns.forEach((btn) => {
      btn.classList.remove("is-loading");
      btn.textContent = "\u{1F504} Sync live prices";
    });
  }
}
