  const boostCostLine = $("sum-boostcost-line");
  if (boostCostLine) boostCostLine.style.display = c.boostCostTotal > 0 ? "" : "none";
  setText("sum-boostcost", `\u2212${fmt(c.boostCostTotal)}`);
  setText("sum-total-label", `\u{1F39F}\uFE0F TOTAL / ${fmt(seasonDays)} DAYS`);
