var tradePendingDeleteId = null;
var tradePendingDeleteType = "active";
function deleteActiveTrade(id) {
  const t = tradeActive.find((x) => x.id === id);
  if (!t) return;
  tradePendingDeleteId = id;
  tradePendingDeleteType = "active";
  const fig = computeTradeFigures(t);
  $("deleteTradeConfirmItem").innerHTML = `
    <span class="trade-card-icon" style="font-size:21.6px;">${getIcon(t.itemName)}</span>
    <div>
      <div class="name">${escapeHtml(t.itemName)}</div>
      <div class="meta">${fmt(t.remainingQty)}\xD7 held \xB7 ${fmt(fig.costBasis)} ${FLOWER_ICON} FLOWER capital</div>
    </div>`;
  $("deleteTradeConfirmOverlay").classList.add("show");
}
function deleteHistoryTrade(id) {
  const t = tradeHistory.find((x) => x.id === id);
  if (!t) return;
  tradePendingDeleteId = id;
  tradePendingDeleteType = "history";
  $("deleteTradeConfirmItem").innerHTML = `
    <span class="trade-card-icon" style="font-size:21.6px;">${getIcon(t.itemName)}</span>
    <div>
      <div class="name">${escapeHtml(t.itemName)}</div>
      <div class="meta">${fmt(t.qty)}\xD7 traded \xB7 ${fmt(t.qty * t.buyPrice)} ${FLOWER_ICON} FLOWER capital</div>
    </div>`;
  $("deleteTradeConfirmOverlay").classList.add("show");
}
$("closeDeleteTradeBtn").onclick = closeDeleteTradeConfirm;
$("cancelDeleteTradeBtn").onclick = closeDeleteTradeConfirm;
$("deleteTradeConfirmOverlay").addEventListener("click", (e) => {
  if (e.target.id === "deleteTradeConfirmOverlay") closeDeleteTradeConfirm();
});
$("confirmDeleteTradeBtn").onclick = () => {
  const id = tradePendingDeleteId;
  const type = tradePendingDeleteType;
  if (type === "history") {
    const t2 = tradeHistory.find((x) => x.id === id);
    if (!t2) {
      closeDeleteTradeConfirm();
      return;
    }
    tradeLifetime.invested = Math.max(0, tradeLifetime.invested - t2.qty * t2.buyPrice);
    tradeLifetime.sold = Math.max(0, tradeLifetime.sold - t2.totalSoldValue);
    tradeHistory = tradeHistory.filter((x) => x.id !== id);
    saveTradeState();
    closeDeleteTradeConfirm();
    renderTradeShop();
    toast("\u{1F5D1} Trade removed");
    return;
  }
  const t = tradeActive.find((x) => x.id === id);
  if (!t) {
    closeDeleteTradeConfirm();
    return;
  }
  tradeLifetime.invested = Math.max(0, tradeLifetime.invested - t.qty * t.buyPrice);
  tradeActive = tradeActive.filter((x) => x.id !== id);
  saveTradeState();
  closeDeleteTradeConfirm();
  renderTradeShop();
  toast("\u{1F5D1} Trade removed");
};
