  const trade = {
    id: tradeGenId(),
    itemName: tradePickedItemName,
    qty,
    buyPrice,
    remainingQty: qty,
    createdAt: Date.now(),
    sells: []
  };
  tradeActive.push(trade);
  tradeLifetime.invested += qty * buyPrice;
  saveTradeState();
  closeNewTradeModal();
