function getAllMaterialCandidates(excludeToolId) {
  const list = [];
  Object.keys(RESOURCE_DATA).forEach((name) => list.push({
    name,
    kindLabel: "Resource"
  }));
  Object.keys(BASE_CROPS).forEach((name) => list.push({
    name,
    kindLabel: "Crop"
  }));
  Object.keys(BASE_FRUITS).forEach((name) => list.push({
    name,
    kindLabel: "Fruit"
  }));
  Object.keys(BASE_GREENHOUSE).forEach((name) => list.push({
    name,
    kindLabel: "Greenhouse"
  }));
  const animalNames = [];
  Object.values(ANIMAL_DATA).forEach((cfg) => cfg.products.forEach((p) => {
    if (!animalNames.includes(p)) animalNames.push(p);
  }));
  animalNames.forEach((name) => list.push({
    name,
    kindLabel: "Animal produce"
  }));
  toolRecipes.forEach((t) => {
    if (String(t.id) === String(excludeToolId)) return;
    if (!t.producesName) return;
    list.push({
      name: t.producesName,
      kindLabel: `Tool product (${t.name})`
    });
  });
  return list;
}
