  const B = ["make me smile big", "make me cry lil", "make me tinkin' hard", "give me big headache", "make me dance jig", "keep me up all night", "make me heart go boom", "make me wanna quit", "make me rich, heehee", "make me broke, oof", "make me miss someone", "give me butterflies", "make me plan big scheme", "make me laugh like fool"];
  const C = ["'bout dat sunflower seed", "'bout gold and gems", "'bout dat pretty farmer", "'bout tomorrow harvest", "'bout me broken heart", "'bout big juicy profit", "'bout dat sneaky trade", "'bout dis lonely night", "'bout SFL to da moon", "'bout me secret crush", "'bout old goblin days", "'bout next big strategy", "'bout dat market crash", "'bout true goblin love"];
  const D = ["heehee~", "yaa!", "uh-oh...", "oh no!", "teehee!", "arrr!", "hmm...", "whee!", "oof!", "gyahaha!", "tsk tsk...", "aww~", "woo!", "sigh..."];
  const E = ["goblin never give up", "such is farmer life", "dat's just goblin luck", "love hard like farmin'", "profit today, loss tomorrow", "goblin heart forever strong", "SFL life pick me up", "one day she notice me", "goblin gotta keep tradin'", "harvest never sleep", "goblin dream big dream", "market always keep goblin guessin'", "heart want what heart want", "goblin gonna make it big"];
