  const loveInner = `<div class="bg-sim-stat"><span>Affection Tools (${heads} \xD7 ${fmtInt(x.opportunities)} love actions = ${fmtInt(x.capacity)} per cycle)</span><span>+${fmtXp(x.loveCycle)} EXP</span></div>${tools}`;
